  // Mejor tocón ponderado: recorre variables, cortes (incluidos los extremos) y sentido.
  function stump(pts, w, dims) {
    let best = null;
    dims.forEach(f => {
      const v = [...new Set(pts.map(p => p[f]))].sort((a, b) => a - b);
      const cuts = [v[0] - 0.5, ...v.slice(0, -1).map((a, i) => (a + v[i + 1]) / 2), v[v.length - 1] + 0.5];
      cuts.forEach(t => [1, -1].forEach(s => {
        let e = 0; pts.forEach((p, i) => { const h = p[f] <= t ? s : -s; if (h !== p[2]) e += w[i]; });
        if (!best || e < best.e - 1e-12) best = { f, t, s, e };
      }));
    });
    return best;
  }
  const hval = (st, p) => (p[st.f] <= st.t ? st.s : -st.s);
  const cache = {};
  function run(key) {
    if (cache[key]) return cache[key];
    const S = SETS[key], n = S.tr.length; let w = Array(n).fill(1 / n); const rounds = [];
    for (let m = 0; m < S.M; m++) {
      const st = stump(S.tr, w, S.dims), e = Math.max(st.e, 1e-10), a = 0.5 * Math.log((1 - e) / e);
      rounds.push({ ...st, e: st.e, a, w: [...w] });
      w = w.map((wi, i) => wi * Math.exp(-a * S.tr[i][2] * hval(st, S.tr[i]))); const z = K.sum(w); w = w.map(x => x / z);
    }
    const F = (p, m) => { let s = 0; for (let k = 0; k < m; k++) s += rounds[k].a * hval(rounds[k], p); return s; };
    const errs = set => rounds.map((_, m) => set.filter(p => Math.sign(F(p, m + 1)) !== p[2]).length / set.length);
    return (cache[key] = { rounds, F, errTr: errs(S.tr), errTe: S.te ? errs(S.te) : null });
  }
  const modeSeg = K.segmented($('#ada-mode'), () => { const S = SETS[modeSeg.get()]; $('#ada-m').max = S.M; if (+$('#ada-m').value > S.M) $('#ada-m').value = 3; render(); });
  const fmtSt = (st, key) => key === 'd1' ? `x ≤ ${K.fmt(st.t, 1)} ⇒ ${st.s > 0 ? '+' : '−'}` : `x${st.f ? '₂' : '₁'} ≤ ${K.fmt(st.t, 2)} ⇒ ${st.s > 0 ? '+' : '−'}`;

  function render() {
    const key = modeSeg.get(), S = SETS[key], m = +$('#ada-m').value, R = run(key), rd = R.rounds[m - 1];
    $('#ada-m-v').textContent = m;
    $('#ada-h').textContent = fmtSt(rd, key); $('#ada-eps').textContent = K.fmt(rd.e, 3); $('#ada-alpha').textContent = K.fmt(rd.a, 3);
    const nErr = Math.round(R.errTr[m - 1] * S.tr.length);
    $('#ada-err').textContent = `${nErr}/${S.tr.length}` + (S.te ? ` · prueba ${K.fmt(R.errTe[m - 1], 3)}` : '');
    $('#ada-leg-te').style.display = S.te ? '' : 'none';
    const wmax = Math.max(...rd.w);
    if (key === 'd1') {
      $('#ada-plot-t').textContent = 'Pesos (tamaño) y puntaje F(x) del ensamble';
      const c = K.chart($('#ada-svg'), { width: 380, height: 280, x: [0.3, 10.7], y: [-2.2, 2.2], margin: { left: 40, bottom: 40 } });
      c.axes({ xTicks: 10, yTicks: 4, xLabel: 'x', yLabel: 'F(x)', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 1) });
      c.zeroLines(); c.line(0.3, 0, 10.7, 0, 'muted line thin');
      const steps = []; for (let x = 0.5; x <= 10.5; x += 0.5) steps.push([x, R.F([x], m)]);
      const fp = []; steps.forEach((s, i) => { fp.push(s); if (i + 1 < steps.length) fp.push([steps[i + 1][0], s[1]]); });
      c.path(fp, 's4 line');
      c.line(rd.t, -2.2, rd.t, 2.2, 's5 line dash');
      c.text(rd.t, 2.0, rd.s > 0 ? '← +   − →' : '← −   + →', { 'text-anchor': 'middle', class: 'strong' });
      S.tr.forEach((p, i) => { const d = c.dot(p[0], p[2] > 0 ? 1.2 : -1.2, 3 + 14 * Math.sqrt(rd.w[i] / wmax) , (p[2] > 0 ? 's1' : 's2') + ' dot');
        d.style.fillOpacity = 0.75; if (Math.sign(R.F(p, m)) !== p[2]) { d.style.stroke = 'var(--lab-text)'; d.style.strokeWidth = 2; } });
      $('#ada-leg-f').style.display = '';
    } else {
      $('#ada-plot-t').textContent = 'Región del ensamble y pesos de los puntos';
      const c = K.chart($('#ada-svg'), { width: 380, height: 380, x: [0, 10], y: [0, 10], margin: { left: 40, right: 12, top: 12, bottom: 40 } });
      const G = 40, st = 10 / G;
      for (let i = 0; i < G; i++) for (let j = 0; j < G; j++) { const p = [(i + 0.5) * st, (j + 0.5) * st]; const r = c.rect(p[0] - st / 2, p[1] - st / 2, p[0] + st / 2, p[1] + st / 2, R.F(p, m) >= 0 ? 's1' : 's2'); r.style.fillOpacity = 0.14; r.style.stroke = 'none'; }
      c.axes({ xTicks: 5, yTicks: 5, xLabel: 'x₁', yLabel: 'x₂', grid: false, xFmt: v => K.fmt(v, 0) });
      const circ = []; for (let k = 0; k <= 64; k++) circ.push([5 + 3 * Math.cos(k / 32 * Math.PI), 5 + 3 * Math.sin(k / 32 * Math.PI)]); c.path(circ, 's3 line dash thin');
      if (rd.f === 0) c.line(rd.t, 0, rd.t, 10, 's5 line dash'); else c.line(0, rd.t, 10, rd.t, 's5 line dash');
      S.tr.forEach((p, i) => { const d = c.dot(p[0], p[1], 2 + 9 * Math.sqrt(rd.w[i] / wmax), (p[2] > 0 ? 's1' : 's2') + ' dot');
        if (Math.sign(R.F(p, m)) !== p[2]) { d.style.stroke = 'var(--lab-text)'; d.style.strokeWidth = 1.8; } });
      $('#ada-leg-f').style.display = 'none';
    }
    const M = S.M, ymax = Math.max(0.4, ...R.errTr, ...(R.errTe || [])) * 1.05;
    const cc = K.chart($('#ada-curve'), { width: 380, height: 260, x: [0, M + 0.5], y: [0, ymax], margin: { left: 44, bottom: 40 } });
    cc.axes({ xTicks: Math.min(M, 5), yTicks: 4, xLabel: 'rondas', yLabel: 'error', xFmt: v => K.fmt(v, 0), yFmt: v => K.fmt(v, 2) });
    cc.path(R.errTr.map((e, k) => [k + 1, e]), 's1 line');
    if (R.errTe) cc.path(R.errTe.map((e, k) => [k + 1, e]), 's4 line');
    cc.dot(m, R.errTr[m - 1], 6, 's2 dot');
    const show = R.rounds.slice(Math.max(0, m - 8), m);
    $('#ada-tab').innerHTML = '<table class="plab-table"><thead><tr><th>Ronda</th><th>Tocón</th><th>ε</th><th>α</th><th>Errores del ensamble</th></tr></thead><tbody>' +
      show.map((r, k) => { const idx = Math.max(0, m - 8) + k; return `<tr${idx === m - 1 ? ' class="hl"' : ''}><td>${idx + 1}</td><td>${fmtSt(r, key)}</td><td>${K.fmt(r.e, 4)}</td><td>${K.fmt(r.a, 4)}</td><td>${Math.round(R.errTr[idx] * S.tr.length)}/${S.tr.length}</td></tr>`; }).join('') + '</tbody></table>';
    const note = $('#ada-note');
    if (key === 'd1') { note.className = nErr ? 'plab-note warn' : 'plab-note good';
      note.textContent = nErr ? `Tras ${m} ronda(s) el ensamble aún falla ${nErr} punto(s). Los puntos grandes son los que la ronda ${m} debe atender: los errores anteriores pesan en conjunto 0.5.` : `Con ${m} tocones el ensamble clasifica bien los diez puntos, aunque cada tocón falla tres o cuatro. Las rondas posteriores siguen repesando, pero el error ya no cambia.`; }
    else { const best = R.errTe.indexOf(Math.min(...R.errTe)); note.className = 'plab-note ' + (m > 60 && R.errTe[m - 1] > Math.min(...R.errTe) + 0.02 ? 'warn' : 'good');
      note.textContent = `Ronda ${m}: error de entrenamiento ${K.fmt(R.errTr[m - 1], 3)} y de prueba ${K.fmt(R.errTe[m - 1], 3)}. La frontera circular se aproxima con escalones. Los puntos con etiqueta invertida acumulan peso ronda tras ronda: AdaBoost es sensible al ruido.`; }
  }
  $('#ada-m').addEventListener('input', render);
  render();
})();
</script>
