``` {.python .cell-code}
import plotly.graph_objects as go
from sklearn.ensemble import BaggingRegressor
from sklearn.metrics import mean_squared_error

def f_real(x):
    return 2 * np.sin(x) + 0.3 * x

def generar_reg(n, semilla):
    rng = np.random.default_rng(semilla)
    x = np.sort(rng.uniform(0, 10, n)).round(2)
    return x, (f_real(x) + rng.normal(0, 0.6, n)).round(2)

x_tr, y_tr = generar_reg(40, 11)
x_te, y_te = generar_reg(300, 12)
X_tr, X_te = x_tr.reshape(-1, 1), x_te.reshape(-1, 1)

for prof in [1, 2, 4, None]:
    t = DecisionTreeRegressor(max_depth=prof, random_state=0).fit(X_tr, y_tr)
    print(f"Árbol único (profundidad {prof}): ECM entrenamiento {mean_squared_error(y_tr, t.predict(X_tr)):.3f}, "
          f"prueba {mean_squared_error(y_te, t.predict(X_te)):.3f}")

Bs = [1, 2, 5, 10, 20, 50, 100, 200]
ecm_bag = [mean_squared_error(y_te, BaggingRegressor(DecisionTreeRegressor(), n_estimators=B, random_state=0)
                              .fit(X_tr, y_tr).predict(X_te)) for B in Bs]
bag_oob = BaggingRegressor(DecisionTreeRegressor(), n_estimators=200, oob_score=True, random_state=0).fit(X_tr, y_tr)
print(f"Bagging con 200 árboles: ECM prueba {ecm_bag[-1]:.3f}, ECM fuera de la bolsa "
      f"{mean_squared_error(y_tr, bag_oob.oob_prediction_):.3f}")

fig = go.Figure(go.Scatter(x=Bs, y=ecm_bag, mode="lines+markers", name="bagging", line=dict(color="#7c3aed")))
fig.add_hline(y=mean_squared_error(y_te, DecisionTreeRegressor(random_state=0).fit(X_tr, y_tr).predict(X_te)),
              line=dict(color="gray", dash="dash"), annotation_text="árbol único")
fig.add_hline(y=0.36, line=dict(color="#16a34a", dash="dot"), annotation_text="error irreducible")
fig.update_layout(xaxis=dict(type="log", title="número de árboles"), yaxis_title="ECM en prueba",
                  height=340, margin=dict(l=10, r=10, t=20, b=40))
fig.show()
