### Error fuera de la bolsa e importancia de variables

::: {#cell-fig-ens-importancia .cell execution_count=5}
``` {.python .cell-code}
from sklearn.inspection import permutation_importance
from plotly.subplots import make_subplots

X_tr2, X_te2, y_tr2, y_te2 = train_test_split(X, y, test_size=0.3, stratify=y, random_state=0)
rf = RandomForestClassifier(n_estimators=500, oob_score=True, random_state=0, n_jobs=-1).fit(X_tr2, y_tr2)
print(f"Exactitud fuera de la bolsa: {rf.oob_score_:.3f} · exactitud en prueba: {rf.score(X_te2, y_te2):.3f}")

mdi = pd.Series(rf.feature_importances_, index=X.columns)
perm = pd.Series(permutation_importance(rf, X_te2, y_te2, n_repeats=20, random_state=0).importances_mean, index=X.columns)
top = mdi.sort_values(ascending=False).index[:10][::-1]
fig = make_subplots(rows=1, cols=2, subplot_titles=("MDI (impureza)", "Permutación (prueba)"), shared_yaxes=True)
fig.add_trace(go.Bar(x=mdi[top], y=top, orientation="h", marker_color="#2563eb"), row=1, col=1)
fig.add_trace(go.Bar(x=perm[top], y=top, orientation="h", marker_color="#ea580c"), row=1, col=2)
fig.update_layout(height=420, showlegend=False, margin=dict(l=10, r=10, t=40, b=30))
fig.show()
```

